import json

REQUIRED = {
    "claim",
    "source",
    "owner",
    "source_type",
    "directness",
    "scope",
    "published_or_updated",
    "verified_on",
    "independence",
    "decision",
    "reason",
}
ALLOWED_TYPES = {"PRIMARY", "SECONDARY", "AGGREGATOR", "UNKNOWN"}
ALLOWED_DIRECTNESS = {
    "DIRECTLY STATES",
    "SUPPORTS INFERENCE",
    "BACKGROUND ONLY",
}
ALLOWED_DECISIONS = {"USE", "CORROBORATE", "BACKGROUND", "REJECT"}

FIXTURE = r'''{
  "cards": [
    {"claim":"Atlas API 5.0 accepts max_tokens","source":"T1","owner":"Atlas Works","source_type":"PRIMARY","directness":"DIRECTLY STATES","scope":"Atlas API 5.0","published_or_updated":"2026-07-02","verified_on":"2026-07-10","independence":"owner-issued","decision":"USE","reason":"Version-specific owner schema directly states the behavior."},
    {"claim":"Atlas is universally fastest","source":"T4","owner":"Atlas Works","source_type":"PRIMARY","directness":"SUPPORTS INFERENCE","published_or_updated":"2026-07-08","verified_on":"2026-07-10","independence":"marketing interest","decision":"REJECT","reason":"No metric or method."},
    {"claim":"Bad decision example","source":"T5","owner":"RiverBench News","source_type":"AGGREGATOR","directness":"DIRECTLY STATES","scope":"copied excerpt","published_or_updated":"2026-07-07","verified_on":"2026-07-10","independence":"copied from T3","decision":"MAYBE","reason":"Invalid decision is intentional."},
    {"claim":"Bad directness example","source":"T6","owner":"UNKNOWN","source_type":"UNKNOWN","directness":"PROVEN","scope":"UNKNOWN","published_or_updated":"UNKNOWN","verified_on":"2026-07-10","independence":"UNKNOWN","decision":"BACKGROUND","reason":"Invalid directness is intentional."},
    ["not", "a", "card"],
    {"claim":["list"],"source":"T1","owner":"Atlas Works","source_type":"PRIMARY","directness":"DIRECTLY STATES","scope":"Atlas API 5.0","published_or_updated":"2026-07-02","verified_on":"2026-07-10","independence":"owner-issued","decision":"USE","reason":"List-valued claim is invalid."}
  ]
}'''

ORIGINAL_MEASUREMENT_CARD = {
    "claim": "The synthetic results table reports a median latency of 240 ms.",
    "source": "synthetic-results.csv",
    "owner": "Example Measurement Group",
    "source_type": "PRIMARY",
    "directness": "DIRECTLY STATES",
    "scope": "One documented synthetic test configuration",
    "published_or_updated": "2026-08-01",
    "verified_on": "2026-09-19",
    "independence": "Original measurement rather than a copied report",
    "decision": "USE",
    "reason": "The synthetic original results table directly reports the measurement.",
}

UNKNOWN_CARD = {
    "claim": "The available material does not identify the test owner.",
    "source": "U1",
    "owner": "UNKNOWN",
    "source_type": "UNKNOWN",
    "directness": "BACKGROUND ONLY",
    "scope": "UNKNOWN",
    "published_or_updated": "UNKNOWN",
    "verified_on": "2026-09-19",
    "independence": "UNKNOWN",
    "decision": "BACKGROUND",
    "reason": "Unknowns are recorded explicitly instead of inferred.",
}

CHANGED_INPUT = json.dumps(
    {
        "cards": [
            UNKNOWN_CARD,
            {
                "claim": "A synthetic summary reports a response-time result.",
                "source": "C2",
                "owner": "   ",
                "source_type": "BLOG",
                "directness": "SUPPORTS INFERENCE",
                "scope": "One synthetic summary",
                "published_or_updated": "2026-09-01",
                "verified_on": "2026-09-19",
                "independence": "UNKNOWN",
                "decision": "CORROBORATE",
                "reason": "The owner is blank and the source-type label is outside the vocabulary.",
            },
        ]
    }
)


def nonempty_scalar(value):
    return isinstance(value, str) and bool(value.strip())


def check_card(number, card):
    if not isinstance(card, dict):
        return [f"CARD {number}: FAIL: card must be an object"]

    problems = []
    missing = sorted(key for key in REQUIRED if key not in card)
    if missing:
        problems.append("missing=" + ",".join(missing))

    for key in sorted(REQUIRED & card.keys()):
        if not nonempty_scalar(card[key]):
            problems.append("nonempty scalar required=" + key)

    if nonempty_scalar(card.get("source_type")):
        if card["source_type"] not in ALLOWED_TYPES:
            problems.append("invalid source_type")
    if nonempty_scalar(card.get("directness")):
        if card["directness"] not in ALLOWED_DIRECTNESS:
            problems.append("invalid directness")
    if nonempty_scalar(card.get("decision")):
        if card["decision"] not in ALLOWED_DECISIONS:
            problems.append("invalid decision")

    if problems:
        return [f"CARD {number}: FAIL: " + "; ".join(problems)]
    return [f"CARD {number}: PASS: structure only"]


def check_packet(packet):
    if not isinstance(packet, dict):
        return ["PACKET: FAIL: top level must be an object"]
    cards = packet.get("cards")
    if not isinstance(cards, list):
        return ["PACKET: FAIL: cards must be a list"]

    diagnostics = []
    for number, card in enumerate(cards, 1):
        diagnostics.extend(check_card(number, card))
    return diagnostics


def validate_json_text(text):
    try:
        packet = json.loads(text)
    except (json.JSONDecodeError, TypeError):
        return ["PACKET: FAIL: invalid JSON"]
    return check_packet(packet)


def altered_card(**changes):
    card = dict(ORIGINAL_MEASUREMENT_CARD)
    card.update(changes)
    return card


def run_assertion_tests():
    expected_fixture = [
        "CARD 1: PASS: structure only",
        "CARD 2: FAIL: missing=scope",
        "CARD 3: FAIL: invalid decision",
        "CARD 4: FAIL: invalid directness",
        "CARD 5: FAIL: card must be an object",
        "CARD 6: FAIL: nonempty scalar required=claim",
    ]
    assert validate_json_text(FIXTURE) == expected_fixture

    assert check_card(1, ORIGINAL_MEASUREMENT_CARD) == [
        "CARD 1: PASS: structure only"
    ]
    assert check_card(1, UNKNOWN_CARD) == [
        "CARD 1: PASS: structure only"
    ]
    assert check_card(1, altered_card(source="   ")) == [
        "CARD 1: FAIL: nonempty scalar required=source"
    ]
    assert check_card(1, altered_card(source_type="BLOG")) == [
        "CARD 1: FAIL: invalid source_type"
    ]
    assert check_card(1, ["malformed", "row"]) == [
        "CARD 1: FAIL: card must be an object"
    ]
    assert check_card(1, altered_card(source_type=["PRIMARY"])) == [
        "CARD 1: FAIL: nonempty scalar required=source_type"
    ]
    assert check_card(1, altered_card(directness={"value": "DIRECTLY STATES"})) == [
        "CARD 1: FAIL: nonempty scalar required=directness"
    ]
    assert check_card(1, altered_card(decision=None)) == [
        "CARD 1: FAIL: nonempty scalar required=decision"
    ]

    assert validate_json_text("[]") == [
        "PACKET: FAIL: top level must be an object"
    ]
    assert validate_json_text("null") == [
        "PACKET: FAIL: top level must be an object"
    ]
    assert validate_json_text('{"cards": {}}') == [
        "PACKET: FAIL: cards must be a list"
    ]
    assert validate_json_text('{"cards": null}') == [
        "PACKET: FAIL: cards must be a list"
    ]
    assert validate_json_text('{"cards": [}') == [
        "PACKET: FAIL: invalid JSON"
    ]

    assert validate_json_text(CHANGED_INPUT) == [
        "CARD 1: PASS: structure only",
        "CARD 2: FAIL: nonempty scalar required=owner; invalid source_type",
    ]


def main():
    run_assertion_tests()
    for line in validate_json_text(FIXTURE):
        print(line)
    print("CHANGED INPUT ANSWER KEY:")
    for line in validate_json_text(CHANGED_INPUT):
        print(line)
    print("SELF-TESTS: PASS")


if __name__ == "__main__":
    main()
